def emit_browser(spec: Mapping[str, Any]) -> dict[str, str]:
    from .game_successor_assets import successor_art
    from .game_successor_runtime import _canonical, _digest, resolved_fidelity

    if spec.get("gameplay_mode") != "top_down":
        raise ValueError("the full browser successor currently requires a topdown recipe")
    encoded = (
        _canonical(spec).decode().replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    )
    page = (
        _HTML.replace("__TITLE__", html.escape(spec["title"]))
        .replace("__SPEC__", encoded)
        .replace("__DIGEST__", _digest(spec))
    )
    page = page.replace(
        "window.SUCCESSOR_SPEC=",
        'window.SUCCESSOR_ART="data:image/png;base64,'
        + successor_art(spec)["png_base64"]
        + '";window.SUCCESSOR_SPEC=',
    )
    page = page.replace(
        "window.SUCCESSOR_SPEC=",
        "window.SUCCESSOR_FIDELITY="
        + json.dumps(resolved_fidelity(spec), separators=(",", ":"))
        + ";window.SUCCESSOR_SPEC=",
    )
    draw_start = _JS.index("function draw(){")
    draw_end = _JS.index("\nfunction makeBar()", draw_start)
    javascript = _JS[:draw_start] + _DRAW + _JS[draw_end:]
    return {
        "game/successor/index.html": page,
        "game/successor/game.js": javascript,
        "game/successor/README.md": "Open index.html in a modern browser. All gameplay, procedural art and synthesized audio are local. No ROM/assets are copied. Save/load stores player state on this device. The backend learning adapter uses the exact same authored 60 Hz mechanics; browser saves grant no learning or production authority.\n",
    }
